import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

// Generated by scripts/sincronizar-piezas.mjs from the channel's publicar/subidos.
const piezas = defineCollection({
	loader: glob({ base: './src/content/piezas', pattern: '**/*.md' }),
	schema: ({ image }) =>
		z.object({
			numero: z.number(),
			titulo: z.string(),
			serie: z.string(),
			portada: image(),
			bajada: z.string(),
			youtube: z.string(),
			// Publish date and ISO 8601 duration of the video, for structured data
			publicada: z.string().optional(),
			duracion: z.string().optional(),
			jugada: z.object({ concepto: z.string(), definicion: z.string() }).optional(),
			narracion: z.array(z.string()),
		}),
});

// Long-form notes, one per piece at most, generated by the same script.
const notas = defineCollection({
	loader: glob({ base: './src/content/notas', pattern: '**/*.md' }),
	schema: z.object({
		titulo: z.string(),
		borrador: z.boolean(),
	}),
});

export const collections = { piezas, notas };
